            SecurityProfile ??= new DiskSecurityProfile();
            SecurityProfile.SecureVMDiskEncryptionSetId = value;
        }
    }

    /// <summary>Determines on how to handle disks with slow I/O.</summary>
    /// <remarks>
    /// Known values (extensible enum AvailabilityPolicyDiskDelay):
    /// <list type="bullet">
    /// <item><description>"None": Defaults to behavior without av policy specified, which is VM restart upon slow disk io.</description></item>
    /// <item><description>"AutomaticReattach": Upon a disk io failure or slow response, try detaching then reattaching the disk.</description></item>
    /// </list>
    /// </remarks>
    [JsonIgnore]
    public string? AvailabilityPolicyActionOnDiskDelay
    {
        get => AvailabilityPolicy?.ActionOnDiskDelay;
        set
        {
            AvailabilityPolicy ??= new AvailabilityPolicy();
            AvailabilityPolicy.ActionOnDiskDelay = value;
        }
    }
}
